import {
  Container,
  Box,
  Grid,
  Typography,
  Tab,
  styled,
  Fade,
  createTheme,
  useMediaQuery,
} from "@mui/material";
import React, { useEffect } from "react";
import { useState } from "react";
import Services from "./Services";
import { TabContext, TabList, TabPanel } from "@mui/lab";
import { useLocation } from "react-router-dom";

const ManageServices = ({ updateServiceType }) => {
  const CustomTab = styled(Tab)(({ theme }) => ({
    fontSize: "12px",
    lineHeight: "16px",
    [theme.breakpoints.up("md")]: {
      fontSize: "20px",
      lineHeight: "28px",
    },
    [theme.breakpoints.up("lg")]: {
      fontSize: "24px",
    },
    fontWeight: 600,

    textTransform: "none",
    textWrap: "nowrap",
  }));
  const location = useLocation();
  const { serviceType } = location.state || {};
  const [service, setService] = useState("engine");
  useEffect(() => {
    if (serviceType) {
      setService(serviceType);
      updateServiceType(serviceType);
    }
  }, []);
  const handleServiceChange = (event, newValue) => {
    setService(newValue);
    updateServiceType(newValue);
  };

  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{
            px: { xs: 0, sm: 10, lg: 15, xl: 20 },
            pt: { lg: 13, xl: 15 },
          }}
        >
          <Box>
            <TabContext value={service}>
              <Box
                sx={{
                  borderBottom: 1,
                  borderColor: "divider",
                }}
              >
                <TabList
                  // variant={isMobile ? "scrollable" : "fullWidth"}
                  variant="fullWidth"
                  onChange={handleServiceChange}
                  aria-label="lab API tabs example"
                  sx={{
                    ".MuiTabs-flexContainer": {
                      display: "flex",
                      justifyContent: "space-between",
                    },
                  }}
                >
                  <CustomTab label="Manage Engine Services" value="engine" />
                  <CustomTab label="Zoho Services" value="zoho" />
                </TabList>
              </Box>
              <Fade in={service === "engine"} timeout={1000}>
                <TabPanel value="engine">
                  <Services service="engine" />
                </TabPanel>
              </Fade>
              <Fade in={service === "zoho"} timeout={1000}>
                <TabPanel value="zoho">
                  <Services service="zoho" />
                </TabPanel>
              </Fade>
            </TabContext>
          </Box>
        </Container>
      </Box>
    </>
  );
};

export default ManageServices;
